function digitAt(n: number): number {
  let d = 1, count = 9, start = 1;
  while (n > d * count) {
    n -= d * count;
    d++;
    count *= 10;
    start *= 10;
  }
  const num = start + Math.floor((n - 1) / d);
  const fromRight = d - 1 - ((n - 1) % d); // digits to drop on the right
  return Math.floor(num / 10 ** fromRight) % 10;
}

